---------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
CREATE PROCEDURE sp_gal_Gallery_CRUD
                                                                                                                                                                                                                         
    @Action NVARCHAR(10),              -- 'SELECT', 'INSERT', 'UPDATE', 'DELETE'
                                                                                                                                                                             
    @MemberID NCHAR(64),               -- Mandatory
                                                                                                                                                                                                          
    @ImageID BIGINT = NULL,            -- Used for update/delete/select single
                                                                                                                                                                               
    @Title NVARCHAR(125) = NULL,
                                                                                                                                                                                                                             
    @Description NVARCHAR(MAX) = NULL,
                                                                                                                                                                                                                       
    @Private NVARCHAR(3) = 'PVT',
                                                                                                                                                                                                                            
    @Image_Thumbnail VARBINARY(MAX) = NULL,
                                                                                                                                                                                                                  
    @Image_Data VARBINARY(MAX) = NULL, -- Stored in gal_Gallery_Images
                                                                                                                                                                                       
    @PostDate DATE = NULL
                                                                                                                                                                                                                                    
AS
                                                                                                                                                                                                                                                           
BEGIN
                                                                                                                                                                                                                                                        
    SET NOCOUNT ON;
                                                                                                                                                                                                                                          

                                                                                                                                                                                                                                                             
    ----------------------------------------------------------------
                                                                                                                                                                                         
    -- Validate mandatory MemberID
                                                                                                                                                                                                                           
    ----------------------------------------------------------------
                                                                                                                                                                                         
    IF @MemberID IS NULL
                                                                                                                                                                                                                                     
    BEGIN
                                                                                                                                                                                                                                                    
        RAISERROR('MemberID is required.', 16, 1);
                                                                                                                                                                                                           
        RETURN;
                                                                                                                                                                                                                                              
    END;
                                                                                                                                                                                                                                                     

                                                                                                                                                                                                                                                             
    ----------------------------------------------------------------
                                                                                                                                                                                         
    -- SELECT (with JOIN to Images)
                                                                                                                                                                                                                          
    ----------------------------------------------------------------
                                                                                                                                                                                         
    IF @Action = 'SELECT'
                                                                                                                                                                                                                                    
    BEGIN
                                                                                                                                                                                                                                                    
        SELECT g.MemberID, g.ImageID, g.Title, g.Description, g.Private, 
                                                                                                                                                                                    
               g.Image_Thumbnail, g.PostDate,
                                                                                                                                                                                                                
               i.Image_data
                                                                                                                                                                                                                                  
        FROM dbo.gal_Gallery g
                                                                                                                                                                                                                               
        LEFT JOIN dbo.gal_Gallery_Images i 
                                                                                                                                                                                                                  
               ON g.MemberID = i.MemberID AND g.ImageID = i.ImageID
                                                                                                                                                                                          
        WHERE g.MemberID = @MemberID
                                                                                                                                                                                                                         
          AND (@ImageID IS NULL OR g.ImageID = @ImageID);
                                                                                                                                                                                                    
        RETURN;
                                                                                                                                                                                                                                              
    END;
                                                                                                                                                                                                                                                     

                                                                                                                                                                                                                                                             
    ----------------------------------------------------------------
                                                                                                                                                                                         
    -- INSERT
                                                                                                                                                                                                                                                
    ----------------------------------------------------------------
                                                                                                                                                                                         
    IF @Action = 'INSERT'
                                                                                                                                                                                                                                    
    BEGIN
                                                                                                                                                                                                                                                    
        -- Generate new ImageID if not supplied
                                                                                                                                                                                                              
        IF @ImageID IS NULL
                                                                                                                                                                                                                                  
        BEGIN
                                                                                                                                                                                                                                                
            SELECT @ImageID = ISNULL(MAX(ImageID),0) + 1
                                                                                                                                                                                                     
            FROM dbo.gal_Gallery
                                                                                                                                                                                                                             
            WHERE MemberID = @MemberID;
                                                                                                                                                                                                                      
        END;
                                                                                                                                                                                                                                                 

                                                                                                                                                                                                                                                             
        INSERT INTO dbo.gal_Gallery
                                                                                                                                                                                                                          
            (MemberID, ImageID, Title, Description, Private, Image_Thumbnail, PostDate)
                                                                                                                                                                      
        VALUES
                                                                                                                                                                                                                                               
            (@MemberID, @ImageID, @Title, @Description, @Private, @Image_Thumbnail, ISNULL(@PostDate, GETDATE()));
                                                                                                                                           

                                                                                                                                                                                                                                                             
        IF @Image_Data IS NOT NULL
                                                                                                                                                                                                                           
        BEGIN
                                                                                                                                                                                                                                                
            INSERT INTO dbo.gal_Gallery_Images
                                                                                                                                                                                                               
                (MemberID, ImageID, Image_data, PostDate)
                                                                                                                                                                                                    
            VALUES
                                                                                                                                                                                                                                           
                (@MemberID, @ImageID, @Image_Data, ISNULL(@PostDate, GETDATE()));
                                                                                                                                                                            
        END;
                                                                                                                                                                                                                                                 

                                                                                                                                                                                                                                                             
        RETURN;
                                                                                                                                                                                                                                              
    END;
                                                                                                                                                                                                                                                     

                                                                                                                                                                                                                                                             
    ----------------------------------------------------------------
                                                                                                                                                                                         
    -- UPDATE
                                                                                                                                                                                                                                                
    ----------------------------------------------------------------
                                                                                                                                                                                         
    IF @Action = 'UPDATE'
                                                                                                                                                                                                                                    
    BEGIN
                                                                                                                                                                                                                                                    
        IF @ImageID IS NULL
                                                                                                                                                                                                                                  
        BEGIN
                                                                                                                                                                                                                                                
            RAISERROR('ImageID is required for UPDATE.', 16, 1);
                                                                                                                                                                                             
            RETURN;
                                                                                                                                                                                                                                          
        END;
                                                                                                                                                                                                                                                 

                                                                                                                                                                                                                                                             
        UPDATE dbo.gal_Gallery
                                                                                                                                                                                                                               
        SET Title = ISNULL(@Title, Title),
                                                                                                                                                                                                                   
            Description = ISNULL(@Description, Description),
                                                                                                                                                                                                 
            Private = ISNULL(@Private, Private),
                                                                                                                                                                                                             
            Image_Thumbnail = ISNULL(@Image_Thumbnail, Image_Thumbnail),
                                                                                                                                                                                     
            PostDate = ISNULL(@PostDate, PostDate)
                                                                                                                                                                                                           
        WHERE MemberID = @MemberID AND ImageID = @ImageID;
                                                                                                                                                                                                   

                                                                                                                                                                                                                                                             
        IF @Image_Data IS NOT NULL
                                                                                                                                                                                                                           
        BEGIN
                                                                                                                                                                                                                                                
            IF EXISTS (SELECT 1 FROM dbo.gal_Gallery_Images WHERE MemberID=@MemberID AND ImageID=@ImageID)
                                                                                                                                                   
                UPDATE dbo.gal_Gallery_Images
                                                                                                                                                                                                                
                SET Image_data = @Image_Data,
                                                                                                                                                                                                                
                    PostDate = ISNULL(@PostDate, PostDate)
                                                                                                                                                                                                   
                WHERE MemberID = @MemberID AND ImageID = @ImageID;
                                                                                                                                                                                           
            ELSE
                                                                                                                                                                                                                                             
                INSERT INTO dbo.gal_Gallery_Images (MemberID, ImageID, Image_data, PostDate)
                                                                                                                                                                 
                VALUES (@MemberID, @ImageID, @Image_Data, ISNULL(@PostDate, GETDATE()));
                                                                                                                                                                     
        END;
                                                                                                                                                                                                                                                 

                                                                                                                                                                                                                                                             
        RETURN;
                                                                                                                                                                                                                                              
    END;
                                                                                                                                                                                                                                                     

                                                                                                                                                                                                                                                             
    ----------------------------------------------------------------
                                                                                                                                                                                         
    -- DELETE
                                                                                                                                                                                                                                                
    ----------------------------------------------------------------
                                                                                                                                                                                         
    IF @Action = 'DELETE'
                                                                                                                                                                                                                                    
   BEGIN
                                                                                                                                                                                                                                                     
        IF @ImageID IS NULL
                                                                                                                                                                                                                                  
        BEGIN
                                                                                                                                                                                                                                                
            RAISERROR('ImageID is required for DELETE.', 16, 1);
                                                                                                                                                                                             
            RETURN;
                                                                                                                                                                                                                                          
        END;
                                                                                                                                                                                                                                                 

                                                                                                                                                                                                                                                             
        DELETE FROM dbo.gal_Gallery_Images
                                                                                                                                                                                                                   
        WHERE MemberID = @MemberID AND ImageID = @ImageID;
                                                                                                                                                                                                   

                                                                                                                                                                                                                                                             
        DELETE FROM dbo.gal_Gallery
                                                                                                                                                                                                                          
        WHERE MemberID = @MemberID AND ImageID = @ImageID;
                                                                                                                                                                                                   

                                                                                                                                                                                                                                                             
        RETURN;
                                                                                                                                                                                                                                              
    END;
                                                                                                                                                                                                                                                     
END
                                                                                                                                                                                                                                                          
